import{c as e,$ as a,Q as o,j as n,g as s,o as d,n as i,m as r}from"./chunks/framework.Ce_49mA8.js";const b=JSON.parse('{"title":"Сервисный цикл","description":"Сквозное пошаговое руководство по сервисному конвейеру мастерской в ОмниКрафт ЕРП — от регистрации клиента и прейскуранта до заказ-наряда, списания расходников со склада и окончательного расчета в кассе.","frontmatter":{"title":"Сервисный цикл","description":"Сквозное пошаговое руководство по сервисному конвейеру мастерской в ОмниКрафт ЕРП — от регистрации клиента и прейскуранта до заказ-наряда, списания расходников со склада и окончательного расчета в кассе.","datePublished":"2026-11-15","dateModified":"2026-11-15","order":10},"headers":[],"relativePath":"ru/docs/spaces/services/cycle.md","filePath":"ru/docs/spaces/services/cycle.md","lastUpdated":1794700800000}'),c={name:"ru/docs/spaces/services/cycle.md"},p={id:"сервисныи-цикл-пошаговое-руководство-мастера-сервиса",tabindex:"-1"};function g(m,t,h,u,f,x){const l=a("DocIcon");return o(),n("div",null,[s("h1",p,[d(l,{name:"workflow"}),t[0]||(t[0]=i(" Сервисный цикл: Пошаговое руководство мастера сервиса ",-1)),t[1]||(t[1]=s("a",{class:"header-anchor",href:"#сервисныи-цикл-пошаговое-руководство-мастера-сервиса","aria-label":'Permalink to "Сервисный цикл: Пошаговое руководство мастера сервиса"'},"​",-1))]),t[2]||(t[2]=r('<p>Сервисный бизнес кардинально отличается от серийного производства. На классическом ремесленном верстаке мастер создает тираж типовых изделий по неизменной технологической карте. В ремонте и сервисном обслуживании каждый приходящий заказ уникален: у одного прибора требуется простая регулировка, у второго — срочная замена изношенных узлов, а третий требует длительной дефектовки и поиска скрытых поломок.</p><p>Когда сервисный учет ведется на клочках бумаги, договоренности теряются в телефонных переписках, а запчасти списываются «на память», мастерская несет скрытые убытки. Забытые авансы вызывают конфликты с заказчиками, неучтенные уплотнители и подшипники создают недостачи на складе, а истинная доходность ремонта оказывается в разы ниже ожидаемой.</p><p>В <strong>ОмниКрафт ЕРП</strong> рабочее пространство «Услуги» организует работу мастерской как строгий пошаговый конвейер. Каждый физический этап обслуживания напрямую связан с финансами: карточка клиента хранит историю обращений, прейскурант задает нормы выработки, оформление наряда фиксирует аванс в кассе, а закрытие работ списывает запчасти со склада и фиксирует чистую маржу сделки.</p><hr><h2 id="сквознои-физическии-пример-сервисного-центра" tabindex="-1">Сквозной физический пример сервисного центра <a class="header-anchor" href="#сквознои-физическии-пример-сервисного-центра" aria-label="Permalink to &quot;Сквозной физический пример сервисного центра&quot;">​</a></h2><p>Чтобы увидеть работу конвейера на реальных данных, разберем типовой заказ электромеханической мастерской: <strong>«Комплексное техническое обслуживание и восстановление щеточного узла тяжелого перфоратора»</strong>:</p><ul><li><strong>Заказчик:</strong> Алексей Воронов (частный строительный подрядчик), обращается повторно.</li><li><strong>Перечень согласованных услуг:</strong><ul><li>Диагностика и дефектовка электроинструмента — фиксированный тариф <code>800,00 ₽</code>;</li><li>Профилактическая переборка, очистка коллектора и юстировка — нормированная работа на <code>1,5</code> часа при ставке мастера <code>1 200,00 ₽/ч</code> и накладных расходах цеха <code>15%</code>.</li></ul></li><li><strong>Запчасти и расходные материалы со склада:</strong><ul><li>Комплект графитовых щеток с пружинами — <code>550,00 ₽</code> (по текущей складской себестоимости);</li><li>Высокотемпературная смазка редуктора и очиститель — <code>250,00 ₽</code>.</li></ul></li><li><strong>Итоговая согласованная стоимость заказа:</strong> <code>5 000,00 ₽</code>.</li><li><strong>Предоплата (аванс):</strong> <code>2 000,00 ₽</code> при передаче инструмента в работу.</li></ul><hr><h2 id="шаг-1-регистрация-заказчика-в-клиентскои-базе" tabindex="-1">Шаг 1. Регистрация заказчика в клиентской базе <a class="header-anchor" href="#шаг-1-регистрация-заказчика-в-клиентскои-базе" aria-label="Permalink to &quot;Шаг 1. Регистрация заказчика в клиентской базе&quot;">​</a></h2><p>Любой качественный сервис начинается с порядка в контактах. Прежде чем принимать инструмент на верстак, зарегистрируйте карточку клиента.</p><p>Перейдите во вкладку <strong>«Клиенты»</strong> и нажмите кнопку <strong>«Новый клиент»</strong>:</p><ol><li><strong>Заполнение контактных данных:</strong> Внесите имя (<em>«Алексей Воронов»</em>) и контактный телефон. Программа автоматически применит удобную маску форматирования номеров.</li><li><strong>Каналы связи и заметки:</strong> Укажите мессенджер для оперативного согласования скрытых дефектов и добавьте служебную пометку (например, <em>«Бригадир отделочников, постоянный заказчик»</em>).</li><li>Нажмите кнопку <strong>«Сохранить»</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Единая клиентская карточка</p><p>ОмниКрафт ЕРП привязывает все оформленные заказ-наряды к идентификатору клиента. В будущем Вы сможете за пару секунд открыть историю ремонтов, проверить дату гарантийных обязательств и увидеть общую выручку по конкретному человеку.</p></div><hr><h2 id="шаг-2-формирование-каталога-услуг-и-тарифов" tabindex="-1">Шаг 2. Формирование каталога услуг и тарифов <a class="header-anchor" href="#шаг-2-формирование-каталога-услуг-и-тарифов" aria-label="Permalink to &quot;Шаг 2. Формирование каталога услуг и тарифов&quot;">​</a></h2><p>Чтобы не рассчитывать стоимость типовых операций с нуля при каждом визите заказчика, мастерская ведет собственный прейскурант.</p><p>Перейдите во вкладку <strong>«Услуги»</strong> и нажмите кнопку <strong>«Добавить услугу»</strong>:</p><p>Система поддерживает две модели формирования цен:</p><ol><li><strong>Фиксированный тариф:</strong> Укажите наименование (<em>«Диагностика и дефектовка»</em>) и точную отпускную стоимость — <code>800,00 ₽</code>. Этот вариант применяется для стандартных операций с известной трудоемкостью.</li><li><strong>Расчетная стоимость по нормо-часам:</strong> Для сложных реставрационных и ремонтных манипуляций укажите нормативное время работы мастера (например, <code>1.5</code> часа). Программа возьмет часовую ставку мастера из Настроек (<code>1 200,00 ₽/ч</code>), прибавит норматив накладных расходов мастерской (<code>15%</code>) и выведет справедливую цену:</li></ol><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Прейскурант услуг</span><div class="formula-heading">Расчетная стоимость нормированной операции</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Цена операции</span><span class="math-op">=</span><span class="math-num">1,5 ч</span><span class="math-op">×</span><span class="math-num">1 200,00 ₽</span><span class="math-op">×</span><span class="math-num">1,15</span><span class="math-op">=</span><span class="math-result">2 070,00 ₽</span></div></div></div><div class="tip custom-block"><p class="custom-block-title">Совет мастера: Защита от демпинга через накладные расходы</p><p>Никогда не оценивайте ремонт исключительно по затраченным часам. В цену часа обязательно должны входить амортизация диагностического оборудования, электроэнергия, освещение верстака и аренда помещения. Процент накладных расходов в ОмниКрафт ЕРП гарантирует, что сервисный центр не сработает в скрытый минус.</p></div><hr><h2 id="шаг-3-открытие-заказ-наряда-и-прием-аванса" tabindex="-1">Шаг 3. Открытие заказ-наряда и прием аванса <a class="header-anchor" href="#шаг-3-открытие-заказ-наряда-и-прием-аванса" aria-label="Permalink to &quot;Шаг 3. Открытие заказ-наряда и прием аванса&quot;">​</a></h2><p>Когда инструмент принят в сервис и план работ утвержден с клиентом, мастер открывает рабочий наряд.</p><p>Перейдите во вкладку <strong>«Заказы»</strong> и нажмите кнопку <strong>«Новый заказ-наряд»</strong>:</p><ol><li><strong>Описание заказа:</strong> Сформулируйте суть задачи (<em>«ТО перфоратора: ревизия редуктора и замена щеток»</em>).</li><li><strong>Привязка клиента:</strong> В поле «Клиент» выберите зарегистрированного заказчика (<em>Алексей Воронов</em>).</li><li><strong>Итоговая сумма:</strong> Укажите согласованную полную стоимость работ с учетом запасных частей — <code>5 000,00 ₽</code>.</li><li><strong>Предоплата (аванс):</strong> Внесите сумму полученного аванса — <code>2 000,00 ₽</code>.</li><li>Нажмите кнопку <strong>«Сохранить»</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Автоматическая проводка аванса в кассу (ДДС)</p><p>Вам не требуется переходить в финансовый раздел и вручную записывать приход денег. ОмниКрафт ЕРП работает по принципу сквозной целостности: в ту же секунду в кассе (вкладка <strong>«ДДС»</strong>) появится доходный ордер на <code>+2 000,00 ₽</code> со статьей <em>«Аванс по заказу»</em> и ссылкой на номер наряда.</p></div><hr><h2 id="шаг-4-комплектация-запчастями-и-списание-со-склада" tabindex="-1">Шаг 4. Комплектация запчастями и списание со склада <a class="header-anchor" href="#шаг-4-комплектация-запчастями-и-списание-со-склада" aria-label="Permalink to &quot;Шаг 4. Комплектация запчастями и списание со склада&quot;">​</a></h2><p>В процессе ремонта мастер берет с материального склада необходимые комплектующие и техническую химию.</p><ol><li>Перейдите во вкладку <strong>«Материалы»</strong> (Склад).</li><li>Найдите в наличии нужные позиции: <em>«Комплект графитовых щеток»</em> (1 шт.) и <em>«Смазка редуктора»</em> (0,1 кг).</li><li>Оформите списание материалов с причиной расхода <em>«Использование в сервисном заказе»</em>.</li></ol><div class="info custom-block"><p class="custom-block-title">Скользящая средняя стоимость (МАК)</p><p>Списание запчастей со склада происходит строго по их фактической учетной цене методом скользящей средней стоимости (МАК). Если щетки из разных партий закупались по 500 и 600 рублей, система спишет деталь по честной средневзвешенной цене <code>550,00 ₽</code>, исключая искажение себестоимости ремонта.</p></div><hr><h2 id="шаг-5-выполнение-работ-и-закрытие-заказ-наряда" tabindex="-1">Шаг 5. Выполнение работ и закрытие заказ-наряда <a class="header-anchor" href="#шаг-5-выполнение-работ-и-закрытие-заказ-наряда" aria-label="Permalink to &quot;Шаг 5. Выполнение работ и закрытие заказ-наряда&quot;">​</a></h2><p>Мастер завершил механическую чистку коллектора, установил новые щетки, заполнил редуктор свежей смазкой и провел контрольные испытания перфоратора под нагрузкой. Инструмент готов к выдаче.</p><p>Во вкладке <strong>«Заказы»</strong> найдите оформленный заказ-наряд и нажмите кнопку <strong>«Завершить заказ»</strong> (иконка с зеленой галочкой в правой части карточки):</p><ol><li><strong>Подтверждение операции:</strong> Программа запросит подтверждение: <em>«Завершить заказ и провести окончательный расчет в кассу ДДС?»</em>.</li><li><strong>Что происходит под капотом системы при подтверждении:</strong><ul><li>Программа рассчитывает полную фактическую себестоимость наряда (стоимость списанных деталей <code>800,00 ₽</code> + нормативная оплата труда мастера <code>1 800,00 ₽</code> + накладные расходы цеха <code>390,00 ₽</code> = <code>2 990,00 ₽</code>);</li><li>Система определяет остаток к оплате клиентом: <code>5 000,00 ₽ − 2 000,00 ₽ = 3 000,00 ₽</code>;</li><li>В кассу мастерской (вкладка <strong>«ДДС»</strong>) автоматически проводится второй приходный ордер на сумму <code>+3 000,00 ₽</code> с примечанием <em>«Окончательная оплата по заказу»</em>;</li><li>Заказ переходит в финальный статус завершенных работ и сохраняется в истории.</li></ul></li></ol><div class="warning custom-block"><p class="custom-block-title">Если заказ отменяется: Безопасный возврат средств</p><p>Если в ходе сложной дефектовки выяснилось, что якорь двигателя сгорел и ремонт экономически нецелесообразен, нажмите кнопку <strong>«Отменить заказ»</strong> (красный крестик). Программа предложит вернуть полученный аванс клиенту и автоматически создаст расходный кассовый ордер в ДДС с обоснованием возврата.</p></div><hr><h2 id="шаг-6-финансовыи-результат-и-замыкание-контура" tabindex="-1">Шаг 6. Финансовый результат и замыкание контура <a class="header-anchor" href="#шаг-6-финансовыи-результат-и-замыкание-контура" aria-label="Permalink to &quot;Шаг 6. Финансовый результат и замыкание контура&quot;">​</a></h2><p>После выдачи исправного инструмента и окончательного расчета контур сделки полностью замыкается:</p><ul><li><strong>Касса (ДДС):</strong> По наряду зафиксировано два прозрачных прихода средств: аванс <code>+2 000,00 ₽</code> и доплата <code>+3 000,00 ₽</code>. В кассу поступило ровно <code>5 000,00 ₽</code>.</li><li><strong>Чистая прибыль сделки:</strong> Из общей выручки наряда вычитается полная себестоимость сервиса (запчасти, время мастера и накладные расходы мастерской):</li></ul><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Финансовый итог наряда</span><div class="formula-heading">Чистая коммерческая прибыль сервисной операции</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Чистая маржа</span><span class="math-op">=</span><span class="math-num">5 000,00 ₽</span><span class="math-op">−</span><span class="math-num">800,00 ₽</span><span class="math-op">−</span><span class="math-num">1 800,00 ₽</span><span class="math-op">−</span><span class="math-num">390,00 ₽</span><span class="math-op">=</span><span class="math-result">2 010,00 ₽</span></div></div></div><ul><li><strong>Аналитика:</strong> Обновляются показатели общей сервисной выручки, средний чек ремонта и диаграмма структуры доходов по клиентам.</li><li><strong>Управленческий баланс (Капитал):</strong> Материальные остатки запчастей на складе уменьшились на <code>800,00 ₽</code>, свободная денежная масса в кассе выросла на <code>5 000,00 ₽</code>. Собственный капитал мастерской увеличился на заработанную чистую прибыль.</li></ul><hr><h2 id="сводная-матрица-движения-ресурсов-сервисного-конвеиера" tabindex="-1">Сводная матрица движения ресурсов сервисного конвейера <a class="header-anchor" href="#сводная-матрица-движения-ресурсов-сервисного-конвеиера" aria-label="Permalink to &quot;Сводная матрица движения ресурсов сервисного конвейера&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Этап сервиса</th><th style="text-align:left;">Вкладка программы</th><th style="text-align:left;">Движение материалов и склада</th><th style="text-align:left;">Касса (ДДС)</th><th style="text-align:left;">Экономический результат</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. Приемка и клиент</strong></td><td style="text-align:left;">Клиенты</td><td style="text-align:left;">Движения нет</td><td style="text-align:left;">Денежных проводок нет</td><td style="text-align:left;">Зафиксированы контакт и анамнез поломки</td></tr><tr><td style="text-align:left;"><strong>2. Прейскурант</strong></td><td style="text-align:left;">Услуги</td><td style="text-align:left;">Движения нет</td><td style="text-align:left;">Денежных проводок нет</td><td style="text-align:left;">Определен норматив трудозатрат и цена</td></tr><tr><td style="text-align:left;"><strong>3. Открытие наряда</strong></td><td style="text-align:left;">Заказы</td><td style="text-align:left;">Резервирование работ</td><td style="text-align:left;">Приход аванса (<code>+2 000 ₽</code>)</td><td style="text-align:left;">Заказ принят, зафиксировано обязательство</td></tr><tr><td style="text-align:left;"><strong>4. Комплектация</strong></td><td style="text-align:left;">Материалы (Склад)</td><td style="text-align:left;">Списание щеток и смазки по МАК</td><td style="text-align:left;">Денежных проводок нет</td><td style="text-align:left;">Материалы перешли в себестоимость ремонта</td></tr><tr><td style="text-align:left;"><strong>5. Закрытие наряда</strong></td><td style="text-align:left;">Заказы</td><td style="text-align:left;">Списание завершено</td><td style="text-align:left;">Окончательный приход (<code>+3 000 ₽</code>)</td><td style="text-align:left;">Наряд закрыт, инструмент выдан клиенту</td></tr><tr><td style="text-align:left;"><strong>6. Замыкание баланса</strong></td><td style="text-align:left;">Аналитика / Капитал</td><td style="text-align:left;">Складской баланс обновлен</td><td style="text-align:left;">Полная выручка оприходована</td><td style="text-align:left;">Зафиксирована чистая прибыль и рост капитала</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Совет опытного мастера: Разделяйте аванс и оплату за результат</p><p>Никогда не приступайте к разборке оборудования и заказу специфических деталей без внесения предоплаты. Аванс покрывает прямые затраты на покупку запчастей и подтверждает серьезность намерений заказчика. Автоматическая связка «Заказ-наряд ➔ ДДС» в ОмниКрафт ЕРП гарантирует, что ни один полученный аванс не потеряется в текущих расходах мастерской.</p></div>',48))])}const v=e(c,[["render",g]]);export{b as __pageData,v as default};
